package com.example.Hospital.Management.System.services; import com.example.Hospital.Management.System.entities.*; import com.example.Hospital.Management.System.dtos.*; import com.example.Hospital.Management.System.repositories.*; import com.example.Hospital.Management.System.exceptions.*; import org.springframework.stereotype.Service; import java.util.*; @Service public class PrescriptionService{private final PrescriptionRepository r;private final MedicalRecordRepository mr;public PrescriptionService(PrescriptionRepository r,MedicalRecordRepository mr){this.r=r;this.mr=mr;} private Prescription find(Long id){return r.findById(id).filter(BaseClass::getIsActive).orElseThrow(()->new ResourceNotFoundException("Prescription not found"));} private PrescriptionDTO dto(Prescription e){return PrescriptionDTO.builder().id(e.getId()).medicineName(e.getMedicineName()).dosage(e.getDosage()).durationDays(e.getDurationDays()).medicalRecordId(e.getMedicalRecord().getId()).build();} private void apply(Prescription e,PrescriptionDTO d){MedicalRecord m=mr.findById(d.getMedicalRecordId()).filter(BaseClass::getIsActive).orElseThrow(()->new ResourceNotFoundException("Medical record not found"));e.setMedicineName(d.getMedicineName());e.setDosage(d.getDosage());e.setDurationDays(d.getDurationDays());e.setMedicalRecord(m);} public PrescriptionDTO create(PrescriptionDTO d){Prescription e=new Prescription();apply(e,d);return dto(r.save(e));} public List<PrescriptionDTO> all(){return r.findByIsActiveTrue().stream().map(this::dto).toList();} public PrescriptionDTO get(Long id){return dto(find(id));} public PrescriptionDTO update(Long id,PrescriptionDTO d){Prescription e=find(id);apply(e,d);return dto(r.save(e));} public void delete(Long id){Prescription e=find(id);e.setIsActive(false);r.save(e);}}
